namespace Cysharp.Threading.Tasks {
 [AsyncMethodBuilder(typeof(Builder<>))] public readonly struct UniTask<T> { readonly Task<T> task; public UniTask(Task<T> task)=>this.task=task; public TaskAwaiter<T> GetAwaiter()=>task.GetAwaiter(); public Task<T> AsTask()=>task; }
 public struct Builder<T> { AsyncTaskMethodBuilder<T> b; public static Builder<T> Create()=>new(){b=AsyncTaskMethodBuilder<T>.Create()}; public UniTask<T> Task=>new(b.Task); public void SetResult(T x)=>b.SetResult(x); public void SetException(Exception e)=>b.SetException(e); public void SetStateMachine(IAsyncStateMachine s)=>b.SetStateMachine(s); public void Start<S>(ref S s) where S:IAsyncStateMachine=>b.Start(ref s); public void AwaitOnCompleted<A,S>(ref A a,ref S s) where A:INotifyCompletion where S:IAsyncStateMachine=>b.AwaitOnCompleted(ref a,ref s); public void AwaitUnsafeOnCompleted<A,S>(ref A a,ref S s) where A:ICriticalNotifyCompletion where S:IAsyncStateMachine=>b.AwaitUnsafeOnCompleted(ref a,ref s); }
}
