namespace Fusion { public struct PlayerRef {} public class NetworkObject { public NetworkRunner Runner; public bool IsValid = true; public bool HasStateAuthority = true; public bool Destroyed; public static bool operator ==(NetworkObject a, NetworkObject b) => (ReferenceEquals(a,null) || a.Destroyed) ? (ReferenceEquals(b,null) || b.Destroyed) : !(ReferenceEquals(b,null) || b.Destroyed) && ReferenceEquals(a,b); public static bool operator !=(NetworkObject a, NetworkObject b) => !(a==b); public override bool Equals(object obj) => ReferenceEquals(this,obj); public override int GetHashCode() => base.GetHashCode(); } public class NetworkRunner { public delegate void OnBeforeSpawned(NetworkRunner r,NetworkObject o); public bool IsRunning=true; public bool ContainsObject=true; public NetworkObject Despawned; public Exception DespawnError; public TaskCompletionSource<NetworkObject> Pending=new(); public OnBeforeSpawned Before; public int SpawnCalls; public bool Exists(NetworkObject o) => ContainsObject && o.Runner == this; public Task<NetworkObject> SpawnAsync(string p,Vector3? v,Quaternion? q,PlayerRef? id,OnBeforeSpawned before) { SpawnCalls++; Before=before; return Pending.Task; } public NetworkObject Spawn(string p,Vector3? v,Quaternion? q,PlayerRef? id,OnBeforeSpawned before)=>new(){Runner=this}; public void Despawn(NetworkObject o) { if(DespawnError!=null) throw DespawnError; Despawned=o; } public bool TryFindObject(int id,out NetworkObject o) {o=null;return false;} } }
namespace Core.Network.FusionAdapter.Spawning { public class NetworkEntityAdapter:INetworkEntity { public NetworkObject Object; public NetworkEntityId Id=>new(); public static INetworkEntity Wrap(NetworkObject o)=>o==null?null:new NetworkEntityAdapter{Object=o}; public static NetworkObject Unwrap(INetworkEntity e)=>(e as NetworkEntityAdapter)?.Object; } }
